async function openLibrary(q){const u=new URL('https://openlibrary.org/search.json');u.searchParams.set('q',q);u.searchParams.set('limit','6');u.searchParams.set('fields','key,title,author_name,first_publish_year,cover_i,subject,publisher,language');const r=await timedFetch(u,{headers:{'user-agent':'TasteConstellation/1.0'}});if(!r.ok)throw new Error(`Open Library ${r.status}`);const d=await r.json();return(d.docs||[]).filter(x=>(x.publisher||[]).length&&!isWebNovelMetadata({title:x.title,tags:x.subject||[]})).map(x=>({id:`openlibrary:${x.key}`,externalId:x.key,title:x.title,originalTitle:null,creator:x.author_name?.slice(0,2).join(', ')||'작자 미상',year:x.first_publish_year||null,mediaType:'BOOK',posterUrl:x.cover_i?`https://covers.openlibrary.org/b/id/${x.cover_i}-M.jpg`:null,description:'Open Library 도서 정보',tags:(x.subject||[]).slice(0,8),publishers:(x.publisher||[]).slice(0,8),editionVerified:true,source:'Open Library'}))}
