async function googleBooks(q,env){if(!env.GOOGLE_BOOKS_API_KEY)return[];const u=new URL('https://www.googleapis.com/books/v1/volumes');u.searchParams.set('q',q);u.searchParams.set('maxResults','6');u.searchParams.set('key',env.GOOGLE_BOOKS_API_KEY);const r=await timedFetch(u);if(!r.ok)throw new Error(`Google Books ${r.status}`);const d=await r.json();return(d.items||[]).filter(x=>{const v=x.volumeInfo||{};return Boolean(v.publisher||v.publishedDate||(v.industryIdentifiers||[]).length)&&!isWebNovelMetadata({title:v.title,description:clean(v.description),categories:v.categories||[]})}).map(x=>{const v=x.volumeInfo||{};return{id:`googlebooks:${x.id}`,externalId:x.id,title:v.title,originalTitle:null,creator:(v.authors||[]).join(', ')||'작자 미상',year:year(v.publishedDate),mediaType:'BOOK',posterUrl:bookImage(v.imageLinks),description:clean(v.description)||'Google Books 도서 정보',tags:(v.categories||[]).slice(0,8),publishers:v.publisher?[v.publisher]:[],editionVerified:true,source:'Google Books'}})}
