async function wikipediaSeriesCover(title){const u=new URL('https://ko.wikipedia.org/w/api.php');for(const[key,value]of Object.entries({action:'query',format:'json',formatversion:'2',generator:'prefixsearch',gpssearch:title,gpsnamespace:'0',gpslimit:'5',prop:'pageimages|pageterms',piprop:'original|thumbnail',pithumbsize:'1200',pilicense:'any',wbptterms:'description',redirects:'1',origin:'*'}))u.searchParams.set(key,value);const response=await timedFetch(u,{headers:{'user-agent':'TasteConstellation/1.0 (series cover selection)'}});if(!response.ok)throw new Error(`Wikipedia ${response.status}`);const data=await response.json(),wanted=searchKey(title),pages=(data.query?.pages||[]).filter(page=>page.original?.source||page.thumbnail?.source).map(page=>{const key=searchKey(page.title),description=(page.terms?.description||[]).join(' ');return{page,score:(key===wanted?100:key.startsWith(wanted)||wanted.startsWith(key)?55:0)+(/만화|코믹|manga|comic/iu.test(description)?20:0)+(page.original?.source?10:0)-(/동음이의|분류:/u.test(`${page.title} ${description}`)?100:0)}}).filter(candidate=>candidate.score>0).sort((a,b)=>b.score-a.score),chosen=pages[0]?.page;if(!chosen)return null;return{posterUrl:String(chosen.original?.source||chosen.thumbnail?.source).replace(/^http:/,'https:'),pageTitle:chosen.title,pageUrl:`https://ko.wikipedia.org/wiki/${encodeURIComponent(String(chosen.title).replace(/ /g,'_'))}`,source:'Wikipedia'}}
