const sameIdentity=(left,right)=>{if(identityFamily(left)!==identityFamily(right))return false;const aliases=new Set(identityAliases(left));if(!identityAliases(right).some(alias=>aliases.has(alias)))return false;if(identityFamily(left)==='PRINT')return true;const a=Number(left.year),b=Number(right.year);return!a||!b||Math.abs(a-b)<=1};
